#pragma once
#ifndef GELU_KERNEL_H
#define GELU_KERNEL_H
#include <cmath>
#include "kernel_operator.h"
#include "kernel_common.h"
#include "gelu_tiling.h"

template <typename T>
class GeluKernel {
public:
    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, GM_ADDR tilingGM, AscendC::TPipe *pipe) {
        CopyTiling(&tiling_, tilingGM);
        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(x), tiling_.M * tiling_.N);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(y), tiling_.M * tiling_.N);
        if ASCEND_IS_AIV {
            pipe_ = pipe; subBlockRows_ = tiling_.blockM / AscendC::GetSubBlockNum();
            pipe_->InitBuffer(xInQ_, 1, tiling_.N * sizeof(T));
            pipe_->InitBuffer(yOutQ_, 1, tiling_.N * sizeof(T));
            if constexpr (!std::is_same_v<T, float>) {
                pipe_->InitBuffer(castBuf_, tiling_.N * sizeof(float));
            }
            pipe_->InitBuffer(cBuf_, tiling_.N * sizeof(float));
        }
    }
    __aicore__ inline void Process() {
        if ASCEND_IS_AIV {
            const int ci = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            for (int li = 0; li < tiling_.tasksPerCore; ++li) {
                const int bx = ci * tiling_.tasksPerCore + li;
                if (bx >= BlockCount()) continue;
                for (int r = 0; r < subBlockRows_; ++r) {
                    const int ri = bx * tiling_.blockM + AscendC::GetSubBlockIdx() * subBlockRows_ + r;
                    if (ri < tiling_.M) ProcessRow(ri);
                }
            }
        }
    }
private:
    __aicore__ inline int32_t BlockCount() const { return (tiling_.M + tiling_.blockM - 1) / tiling_.blockM; }
    __aicore__ inline void CopyIn(int32_t ri) {
        xInQ_.AllocTensor<T>(xInL_); AscendC::DataCopy(xInL_, xGM_[ri * tiling_.N], tiling_.N); xInQ_.EnQue(xInL_);
    }
    __aicore__ inline void CopyOut(int32_t ri) {
        yOutQ_.DeQue<T>(yOutL_); AscendC::DataCopy(yGM_[ri * tiling_.N], yOutL_, tiling_.N); yOutQ_.FreeTensor(yOutL_);
    }
    __aicore__ inline void ComputeRow(int32_t ri) {
        xInQ_.DeQue<T>(xInL_); yOutQ_.AllocTensor<T>(yOutL_);
        if constexpr (std::is_same_v<T, float>) {
            auto xFp32 = xInL_.template ReinterpretCast<float>();
            auto yFp32 = yOutL_.template ReinterpretCast<float>();
            auto tmp = cBuf_.Get<float>();
            // GELU: 0.5*x*(1+tanh(0.7978845608*(x+0.044715*x^3)))
            AscendC::Mul(tmp, xFp32, xFp32, tiling_.N); // x^2
            AscendC::Mul(tmp, tmp, xFp32, tiling_.N);    // x^3
            AscendC::Muls(tmp, tmp, 0.044715f, tiling_.N);
            AscendC::Add(tmp, xFp32, tmp, tiling_.N);
            AscendC::Muls(tmp, tmp, 0.7978845608f, tiling_.N);
            AscendC::Tanh(tmp, tmp, tiling_.N);
            AscendC::Adds(tmp, tmp, 1.0f, tiling_.N);
            AscendC::Mul(yFp32, xFp32, tmp, tiling_.N);
            AscendC::Muls(yFp32, yFp32, 0.5f, tiling_.N);
        } else {
            auto xFp32 = castBuf_.Get<float>(); auto yFp32 = cBuf_.Get<float>();
            AscendC::Cast(xFp32, xInL_, AscendC::RoundMode::CAST_NONE, tiling_.N);
            AscendC::PipeBarrier<PIPE_V>();
            AscendC::Mul(yFp32, xFp32, xFp32, tiling_.N);
            AscendC::Mul(yFp32, yFp32, xFp32, tiling_.N);
            AscendC::Muls(yFp32, yFp32, 0.044715f, tiling_.N);
            AscendC::Add(yFp32, xFp32, yFp32, tiling_.N);
            AscendC::Muls(yFp32, yFp32, 0.7978845608f, tiling_.N);
            AscendC::Tanh(yFp32, yFp32, tiling_.N);
            AscendC::Adds(yFp32, yFp32, 1.0f, tiling_.N);
            AscendC::Mul(yFp32, xFp32, yFp32, tiling_.N);
            AscendC::Muls(yFp32, yFp32, 0.5f, tiling_.N);
            AscendC::Cast(yOutL_, yFp32, AscendC::RoundMode::CAST_NONE, tiling_.N);
            AscendC::PipeBarrier<PIPE_V>();
        }
        yOutQ_.EnQue(yOutL_); xInQ_.FreeTensor(xInL_);
    }
    __aicore__ inline void ProcessRow(int ri) { CopyIn(ri); ComputeRow(ri); CopyOut(ri); }
private:
    GeluKernelTiling tiling_{}; AscendC::TPipe *pipe_{}; int subBlockRows_{};
    AscendC::GlobalTensor<T> xGM_, yGM_;
    AscendC::TQue<AscendC::TPosition::VECIN,0> xInQ_;
    AscendC::TQue<AscendC::TPosition::VECOUT,0> yOutQ_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> castBuf_, cBuf_;
    AscendC::LocalTensor<T> xInL_, yOutL_;
};
#endif

